def test_output_residue(run, x):
    a = int(run(x).strip())
    assert 0 <= a < 1000000007

def test_singleton_diagonal(run, x):
    L, R = map(int, x.split())
    a = int(run(x).strip())
    if L == R:
        assert a == 1

def test_interval_4_6(run, x):
    L, R = map(int, x.split())
    a = int(run(x).strip())
    if (L, R) == (4, 6):
        z = sum(y % q == (y ^ q) for q in range(L, R + 1) for y in range(q, R + 1))
        assert a == z

