def test_complete_binary_block(run, x):
    L, R = map(int, x.split())
    a = int(run(x).strip())
    if (L, R) == (524288, 1048575):
        assert a == pow(3, 19, 1000000007)

def test_large_prefix(run, x):
    L, R = map(int, x.split())
    a = int(run(x).strip())
    if L == 1:
        mod = 1000000007
        loose = 0
        tight = 1
        for b in range(R.bit_length() - 1, -1, -1):
            bit = (R >> b) & 1
            loose = (loose * 3 + (tight if bit else 0)) % mod
            tight = tight * (2 if bit else 1) % mod
        total = (loose + tight) % mod
        assert a == ((total - 1) * pow(2, mod - 2, mod)) % mod

def test_enumerate_intervals(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p)):
        for r in range(l + 1, len(p)):
            expected += sorted(p[l:r + 1])[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_incremental_top_two(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p) - 1):
        largest = -1
        second = -1
        for r in range(l, len(p)):
            value = p[r]
            if value > largest:
                second, largest = largest, value
            elif value > second:
                second = value
            if r > l:
                expected += second
    out = run(x)
    assert out.strip() == str(expected)

def test_descending_second_rank(run, x):
    p = list(map(int, x.split()[1:]))
    expected = sum(
        sorted(p[l:r + 1], reverse=True)[1]
        for l in range(len(p))
        for r in range(l + 1, len(p))
    )
    out = run(x)
    assert out.strip() == str(expected)

def test_right_endpoint_enumeration(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for r in range(1, len(p)):
        for l in range(r):
            interval = p[l:r + 1]
            expected += sorted(interval)[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_pair_then_extension(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left in range(len(p) - 1):
        for right in range(left + 1, len(p)):
            values = list(p[left:right + 1])
            values.sort()
            expected += values[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_running_sorted_window(run, x):
    import bisect
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p) - 1):
        window = []
        for r in range(l, len(p)):
            bisect.insort(window, p[r])
            if r != l:
                expected += window[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_max_excluding_one(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p)):
        for r in range(l + 1, len(p)):
            values = p[l:r + 1]
            greatest = max(values)
            expected += max(v for v in values if v != greatest)
    out = run(x)
    assert out.strip() == str(expected)

def test_rank_from_ascending_copy(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p)):
        for r in range(l + 1, len(p)):
            ordered = list(p[l:r + 1])
            ordered.sort()
            expected += ordered[len(ordered) - 2]
    out = run(x)
    assert out.strip() == str(expected)

def test_all_subarrays_length_two_or_more(run, x):
    p = list(map(int, x.split()[1:]))
    answers = []
    for start in range(len(p)):
        for end in range(start + 1, len(p)):
            answers.append(sorted(p[start:end + 1])[-2])
    out = run(x)
    assert out.strip() == str(sum(answers))

def test_explicit_interval_values(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for l in range(len(p) - 1):
        for r in range(l + 1, len(p)):
            values = []
            for index in range(l, r + 1):
                values.append(p[index])
            expected += sorted(values)[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_remove_each_hold(run, x):
    a = list(map(int, x.split()[1:]))
    best = min(max((a[:i] + a[i + 1:])[j + 1] - (a[:i] + a[i + 1:])[j] for j in range(len(a) - 2)) for i in range(1, len(a) - 1))
    assert run(x).strip() == str(best)

def test_retained_track_difficulty(run, x):
    a = list(map(int, x.split()[1:]))
    scores = []
    for removed in range(1, len(a) - 1):
        kept = [v for i, v in enumerate(a) if i != removed]
        scores.append(max(b - c for c, b in zip(kept, kept[1:])))
    assert run(x).strip() == str(min(scores))

def test_joined_neighbor_gap(run, x):
    a = list(map(int, x.split()[1:]))
    gaps = [a[i + 1] - a[i] for i in range(len(a) - 1)]
    scores = []
    for i in range(1, len(a) - 1):
        after = gaps[:i - 1] + [a[i + 1] - a[i - 1]] + gaps[i + 1:]
        scores.append(max(after))
    assert run(x).strip() == str(min(scores))

def test_minimum_over_deletions(run, x):
    a = list(map(int, x.split()[1:]))
    answer = 10 ** 9
    for skip in range(1, len(a) - 1):
        previous = a[0]
        difficulty = 0
        for i in range(1, len(a)):
            if i != skip:
                difficulty = max(difficulty, a[i] - previous)
                previous = a[i]
        answer = min(answer, difficulty)
    assert run(x).strip() == str(answer)

def test_explicit_kept_sequence(run, x):
    a = list(map(int, x.split()[1:]))
    candidates = []
    for omit in range(1, len(a) - 1):
        kept = a[:omit] + a[omit + 1:]
        candidates.append(max(kept[i] - kept[i - 1] for i in range(1, len(kept))))
    assert run(x).strip() == str(min(candidates))

def test_interior_choice_scan(run, x):
    a = list(map(int, x.split()[1:]))
    best = None
    for removed in range(1, len(a) - 1):
        last = None
        worst = 0
        for index, height in enumerate(a):
            if index == removed:
                continue
            if last is not None:
                worst = max(worst, height - last)
            last = height
        best = worst if best is None else min(best, worst)
    assert run(x).strip() == str(best)

def test_post_removal_max_gap(run, x):
    a = list(map(int, x.split()[1:]))
    difficulties = []
    for removed in range(1, len(a) - 1):
        difficulty = 0
        left = 0
        for right in range(1, len(a)):
            if right != removed:
                difficulty = max(difficulty, a[right] - a[left])
                left = right
        difficulties.append(difficulty)
    assert run(x).strip() == str(min(difficulties))

def test_exhaustive_legal_removal(run, x):
    a = list(map(int, x.split()[1:]))
    values = []
    for k in range(1, len(a) - 1):
        value = 0
        retained = [a[i] for i in range(len(a)) if i != k]
        for i in range(len(retained) - 1):
            value = max(value, retained[i + 1] - retained[i])
        values.append(value)
    assert run(x).strip() == str(min(values))

def test_track_definition_oracle(run, x):
    a = list(map(int, x.split()[1:]))
    expected = min(
        max(a[right] - a[left] for left, right in zip([j for j in range(len(a)) if j != removed], [j for j in range(len(a)) if j != removed][1:]))
        for removed in range(1, len(a) - 1)
    )
    assert run(x).strip() == str(expected)

def test_endpoint_preserving_optimum(run, x):
    a = list(map(int, x.split()[1:]))
    optimum = 10 ** 9
    for removed in range(1, len(a) - 1):
        remaining = []
        for i in range(len(a)):
            if i != removed:
                remaining.append(a[i])
        score = max(remaining[i + 1] - remaining[i] for i in range(len(remaining) - 1))
        optimum = min(optimum, score)
    assert run(x).strip() == str(optimum)

