def test_directional_bruteforce(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                for di, dj in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                    y, z = i + di, j + dj
                    while 0 <= y < n and 0 <= z < m:
                        if g[y][z] == 1:
                            want += 1
                            break
                        y += di
                        z += dj
    assert run(x).strip() == str(want)

def test_row_column_rays(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = sum(
        1
        for i in range(n)
        for j in range(m)
        if g[i][j] == 0
        for ray in (g[i][:j], g[i][j + 1:], [g[k][j] for k in range(i)], [g[k][j] for k in range(i + 1, n)])
        if 1 in ray
    )
    assert run(x).strip() == str(want)

def test_prefix_suffix_scan(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        seen = False
        for j in range(m):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
        seen = False
        for j in range(m - 1, -1, -1):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
    for j in range(m):
        seen = False
        for i in range(n):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
        seen = False
        for i in range(n - 1, -1, -1):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
    assert run(x).strip() == str(want)

def test_cellwise_direction_sum(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                want += sum((
                    any(g[i][k] == 1 for k in range(j)),
                    any(g[i][k] == 1 for k in range(j + 1, m)),
                    any(g[k][j] == 1 for k in range(i)),
                    any(g[k][j] == 1 for k in range(i + 1, n)),
                ))
    assert run(x).strip() == str(want)

def test_explicit_step_rays(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    for step in range(1, max(n, m)):
                        y, z = i + di * step, j + dj * step
                        if not (0 <= y < n and 0 <= z < m):
                            break
                        if g[y][z] == 1:
                            want += 1
                            break
    assert run(x).strip() == str(want)

def test_transposed_ray_enumeration(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i, row in enumerate(g):
        for j, value in enumerate(row):
            if value == 0:
                horizontal = (row[:j], row[j + 1:])
                column = [g[k][j] for k in range(n)]
                vertical = (column[:i], column[i + 1:])
                want += sum(1 in ray for ray in horizontal + vertical)
    assert run(x).strip() == str(want)

def test_nearest_or_any_actor(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
