def test_full_timeline(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.extend((teams[side], num, t))
        else: yellow.add(key)
    assert run(x).split() == expected

def test_output_rows(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append([teams[side], num, t])
        else: yellow.add(key)
    assert [line.split() for line in run(x).splitlines() if line.split()] == expected

def test_event_count(run, x):
    p = x.splitlines(); yellow = set(); red = set(); count = 0
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); count += 1
        else: yellow.add(key)
    assert len(run(x).split()) == 3 * count

def test_team_identity(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(teams[side])
        else: yellow.add(key)
    assert run(x).split()[::3] == expected

def test_player_identity(run, x):
    p = x.splitlines(); yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(num)
        else: yellow.add(key)
    assert run(x).split()[1::3] == expected

def test_red_minutes(run, x):
    p = x.splitlines(); yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(t)
        else: yellow.add(key)
    assert run(x).split()[2::3] == expected

def test_chronological_minutes(run, x):
    p = x.splitlines(); yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(t)
        else: yellow.add(key)
    out = run(x).split()
    assert len(out) % 3 == 0 and out[2::3] == expected

def test_direct_red_events(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append((teams[side], num, t, card))
        else: yellow.add(key)
    out = run(x).split(); actual = list(zip(out[::3], out[1::3], out[2::3]))
    assert [row for row, event in zip(actual, expected) if event[3] == 'r'] == [event[:3] for event in expected if event[3] == 'r']

def test_second_yellow_events(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append((teams[side], num, t, card))
        else: yellow.add(key)
    out = run(x).split(); actual = list(zip(out[::3], out[1::3], out[2::3]))
    assert [row for row, event in zip(actual, expected) if event[3] == 'y'] == [event[:3] for event in expected if event[3] == 'y']

def test_empty_red_case(run, x):
    p = x.splitlines(); yellow = set(); red = set()
    for line in p[3:]:
        t, side, num, card = line.split(); key = (side, num)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow): red.add(key)
        else: yellow.add(key)
    assert bool(run(x).split()) == bool(red)

