def test_direct_resolution(run, x):
 a=[z.split() for z in x.splitlines() if z.strip()]; n=int(a[0][0]); i=1; g={}; r=tuple(a[1])
 for _ in range(n):
  u=tuple(a[i]); q=int(a[i+1][0]); g[u]=[tuple(z) for z in a[i+2:i+2+q]]; i+=q+2
 s={r[0]:r}; f=[r]
 while f:
  c={}
  for u in f:
   for v in g[u]:
    if v[0] not in s and (v[0] not in c or int(v[1])>int(c[v[0]][1])): c[v[0]]=v
  s.update(c); f=list(c.values())
 e=[str(len(s)-1)]+[q for k in sorted(s) if k!=r[0] for q in s[k]]
 assert run(x).split()==e

def test_distance_priority(run, x):
 a=[z.split() for z in x.splitlines() if z.strip()]; n=int(a[0][0]); i=1; g={}; r=tuple(a[1])
 for _ in range(n):
  u=tuple(a[i]); q=int(a[i+1][0]); g[u]=[tuple(z) for z in a[i+2:i+2+q]]; i+=q+2
 s={r[0]:r}; f=[r]
 while f:
  c={}
  for u in f:
   for v in g[u]:
