def test_output_two_integers(run, x):
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        scores = [int(token) for token in tokens]
    except ValueError:
        assert False
    assert scores[0] >= 0 and scores[1] >= 0

def test_score_conservation(run, x):
    values = list(map(int, x.split()))
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        first, second = map(int, tokens)
    except ValueError:
        assert False
    assert first + second == sum(values[1:])

def test_score_bounds(run, x):
    values = list(map(int, x.split()))
    total = sum(values[1:])
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        first, second = map(int, tokens)
    except ValueError:
        assert False
    assert 0 <= first <= total and 0 <= second <= total

def test_single_card(run, x):
    values = list(map(int, x.split()))
    n, cards = values[0], values[1:]
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        result = tuple(map(int, tokens))
    except ValueError:
        assert False
    if n == 1:
        assert result == (cards[0], 0)
    else:
        assert result[0] + result[1] == sum(cards)

def test_two_cards(run, x):
    values = list(map(int, x.split()))
    n, cards = values[0], values[1:]
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        result = tuple(map(int, tokens))
    except ValueError:
        assert False
    if n == 2:
        assert result == (max(cards), min(cards))
    else:
        assert result[0] + result[1] == sum(cards)

def test_three_cards_greedy(run, x):
    values = list(map(int, x.split()))
    n, cards = values[0], values[1:]
    tokens = run(x).split()
    assert len(tokens) == 2
    try:
        result = tuple(map(int, tokens))
    except ValueError:
        assert False
    if n == 3:
        left, right = 0, n - 1
        score = [0, 0]
        for turn in range(n):
            if cards[left] > cards[right]:
                score[turn % 2] += cards[left]
                left += 1
            else:
                score[turn % 2] += cards[right]
                right -= 1
        assert result == tuple(score)
    else:
        assert result[0] + result[1] == sum(cards)

