    leaves = [v for v in range(n) if not ch[v]]; k = len(leaves); answer = 1
    for t in range(1, k + 1):
        for chosen in combinations(leaves, k - t + 1):
            high = set(chosen); good = [False] * n
            for v in range(n - 1, -1, -1):
                good[v] = v in high if not ch[v] else (any(good[w] for w in ch[v]) if op[v] else all(good[w] for w in ch[v]))
