def test_threshold_masks(run, x):
    d = list(map(int, x.split())); n = d[0]; ops = d[1:n + 1]
    tree = [[] for _ in range(n)]
    for v, p in enumerate(d[n + 1:], 1): tree[p - 1].append(v)
    leaves = [v for v in range(n) if not tree[v]]; k = len(leaves); want = 1
    for t in range(1, k + 1):
        for mask in range(1 << k):
            if mask.bit_count() != k - t + 1: continue
            def good(v):
                if not tree[v]: return bool(mask & (1 << leaves.index(v)))
